INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist hybride Verschlüsselung nur für große Datenmengen geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Effizient für alle Größen"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit hybrider Verschlüsselung?', 3, '[{"text": "Effiziente und sichere Datenübertragung", "correct": true, "because": "Kombiniert Vorteile beider Methoden"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Langsame Verarbeitung", "correct": false, "because": "Effizienz im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zur hybriden Verschlüsselung?', 5, '[{"text": "Symmetrischer Schlüssel", "correct": true, "because": "Für schnelle Datenverschlüsselung"}, {"text": "Asymmetrischer Schlüssel", "correct": true, "because": "Für sicheren Schlüsselaustausch"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) TLS nutzt hybride Verschlüsselung. b) Sie verwendet nur einen Schlüssel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kombiniert beide Schlüsseltypen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei hybrider Verschlüsselung?', 4, '[{"text": "Schlüsselaustausch", "correct": false, "because": "Kern der Methode"}, {"text": "Symmetrische Effizienz", "correct": false, "because": "Wichtig für Geschwindigkeit"}, {"text": "Visuelles Design", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob hybride Verschlüsselung symmetrische und asymmetrische Vorteile kombiniert?', 2, '[{"text": "Ja", "correct": true, "because": "Geschwindigkeit und Sicherheit"}, {"text": "Nein", "correct": false, "because": "Hauptmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll nutzt hybride Verschlüsselung?', 3, '[{"text": "TLS", "correct": true, "because": "Kombiniert beide Methoden"}, {"text": "HTTP", "correct": false, "because": "Unsicher"}, {"text": "FTP", "correct": false, "because": "Keine Verschlüsselung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur hybriden Verschlüsselung?', 5, '[{"text": "Schlüsselaustausch (asymmetrisch)", "correct": true, "because": "Sicherer Austausch"}, {"text": "Datenverschlüsselung (symmetrisch)", "correct": true, "because": "Effiziente Verarbeitung"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Nicht relevant"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Hybride Verschlüsselung ist sicherer als symmetrische allein. b) Sie ist langsamer als asymmetrische. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schneller durch Symmetrie"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für hybride Verschlüsselung?', 4, '[{"text": "Public Key", "correct": false, "because": "Für Schlüsselaustausch"}, {"text": "Symmetrischer Schlüssel", "correct": false, "because": "Für Datenverschlüsselung"}, {"text": "Grafisches Design", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzt hybride Verschlüsselung nur asymmetrische Methoden?', 2, '[{"text": "Nein", "correct": true, "because": "Kombiniert beide"}, {"text": "Ja", "correct": false, "because": "Symmetrie enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien verwenden hybride Verschlüsselung?', 4, '[{"text": "SSL/TLS", "correct": true, "because": "Sichert Webkommunikation"}, {"text": "PGP", "correct": true, "because": "Sichert E-Mails"}, {"text": "HTTP", "correct": false, "because": "Unsicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass hybride Verschlüsselung komplex ist. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Kombination erfordert Planung"}, {"text": "Nein", "correct": false, "because": "Effizient bei richtiger Umsetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei hybrider Verschlüsselung?', 3, '[{"text": "Sicherer Schlüsselaustausch", "correct": true, "because": "Schützt symmetrischen Schlüssel"}, {"text": "Schnelle Übertragung", "correct": false, "because": "Sekundär"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Hybride Verschlüsselung nutzt RSA für Schlüsselaustausch. b) Sie ist nur für kleine Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Für alle Datengrößen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet hybride Verschlüsselung?', 5, '[{"text": "Schnelligkeit", "correct": true, "because": "Symmetrische Verschlüsselung"}, {"text": "Sicherheit", "correct": true, "because": "Asymmetrischer Austausch"}, {"text": "Maximale Speichergröße", "correct": false, "because": "Nicht relevant"}, {"text": "Datenbankdesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei hybrider Verschlüsselung unwichtig?', 3, '[{"text": "Schlüsselmanagement", "correct": false, "because": "Sichert beide Schlüssel"}, {"text": "Algorithmuswahl", "correct": false, "because": "Bestimmt Schutz"}, {"text": "Schriftgröße", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist hybride Verschlüsselung langsamer als symmetrische?', 3, '[{"text": "Nein", "correct": true, "because": "Symmetrische Phase schnell"}, {"text": "Ja", "correct": false, "because": "Effizient durch Kombination"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob hybride Verschlüsselung Authentizität sichert?', 2, '[{"text": "Ja", "correct": true, "because": "Asymmetrische Schlüssel bestätigen"}, {"text": "Nein", "correct": false, "because": "Teil der Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll wähle ich für hybride Verschlüsselung?', 4, '[{"text": "TLS", "correct": true, "because": "Kombiniert beide Methoden"}, {"text": "FTP", "correct": false, "because": "Unsicher"}, {"text": "Telnet", "correct": false, "because": "Keine Verschlüsselung"}]');
